const input = $input.first().json;
const body = input.body || input;

// Validation
const hasImage = !!(body.image_url || body.image_base64);
const hasMistralKey = !!body.mistral_api_key;

const errors = [];
if (!hasImage) errors.push('image_url ou image_base64 requis');
if (!hasMistralKey) errors.push('mistral_api_key requis');

// Fonction pour détecter le MIME type depuis les magic bytes base64
function detectMimeFromBase64(base64) {
  const prefix = base64.substring(0, 20);
  if (prefix.startsWith('/9j/')) return 'image/jpeg';
  if (prefix.startsWith('iVBOR')) return 'image/png';
  if (prefix.startsWith('R0lG')) return 'image/gif';
  if (prefix.startsWith('UklGR')) return 'image/webp';
  if (prefix.startsWith('Qk')) return 'image/bmp';
  return 'image/png';
}

// Fonction pour obtenir le MIME type depuis l'extension
function getMimeFromExtension(ext) {
  const map = {
    'jpg': 'image/jpeg', 'jpeg': 'image/jpeg',
    'png': 'image/png', 'gif': 'image/gif',
    'webp': 'image/webp', 'bmp': 'image/bmp',
    'tiff': 'image/tiff', 'tif': 'image/tiff'
  };
  return map[(ext || '').toLowerCase()] || null;
}

// Préparer l'image avec détection MIME intelligente
let imageUrl = '';
let detectedMime = 'image/png';

if (body.image_url) {
  imageUrl = body.image_url;
} else if (body.image_base64) {
  // 1. Essayer depuis file_type param
  if (body.file_type) {
    detectedMime = getMimeFromExtension(body.file_type) || 'image/png';
  } else {
    // 2. Détecter depuis magic bytes
    detectedMime = detectMimeFromBase64(body.image_base64);
  }
  imageUrl = 'data:' + detectedMime + ';base64,' + body.image_base64;
}

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    imageUrl: imageUrl,
    detectedMime: detectedMime,
    mistralApiKey: body.mistral_api_key,
    includeImages: body.include_images || false,
    source: body.image_url ? 'url' : 'base64'
  }
}];

const input = $input.first().json;
const prevData = $('Validation').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Vérifier erreur
if (statusCode >= 400) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.message || data.error?.message || 'Mistral API error',
        status: 'API_ERROR'
      }
    }
  }];
}

// Extraire le texte
const text = data.pages?.map(p => p.markdown).join('\n\n') || '';

return [{
  json: {
    success: true,
    data: {
      text: text,
      pages: data.pages || [],
      model: data.model || 'mistral-ocr-latest',
      source: prevData.source
    },
    meta: {
      provider: 'mistral',
      usage: {
        pages_processed: data.usage_info?.pages_processed || 1,
        doc_size_bytes: data.usage_info?.doc_size_bytes || 0
      }
    }
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];
